import{_ as p,a0 as r,w as m,s as a,ao as l,I as n,a1 as e,A as s,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"初级：如何在 Linux Mint 上安装 Google Chrome | LCTT x X-CMD","titleTemplate":false,"description":"初级：如何在 Linux Mint 上安装 Google Chrome | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初级：如何在 Linux Mint 上安装 Google Chrome | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初级：如何在 Linux Mint 上安装 Google Chrome | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip","title":"初级：如何在 Linux Mint 上安装 Google Chrome","tag":"202108","desc":""},"relativePath":"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip.md","filePath":"[post].md"}'),g={name:"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip.md"};function u(d,o,h,f,C,x){const i=r("Link");return m(),a("div",null,[o[22]||(o[22]=l('<h1 id="初级-如何在-linux-mint-上安装-google-chrome" tabindex="-1">初级：如何在 Linux Mint 上安装 Google Chrome <a class="header-anchor" href="#初级-如何在-linux-mint-上安装-google-chrome" aria-label="Permalink to “初级：如何在 Linux Mint 上安装 Google Chrome”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202108/08/133301ni5k5i8rziezwe5i.jpg" alt=""></p><p>这应该是一个非常简单的话题，但我写这个是因为我看到很多网站推荐在 Linux Mint 上安装 Google Chrome 的奇怪命令行步骤。那是可行的，但那是不必要的复杂，特别是对于不熟悉命令行的初学者。</p><p>实际上，你根本不需要走终端方式。你所要做的就是去谷歌浏览器的网站，下载 Ubuntu 的安装文件并安装。</p><p>让我详细介绍一下步骤，供你了解。</p><h3 id="在-linux-mint-上安装-google-chrome" tabindex="-1">在 Linux Mint 上安装 Google Chrome <a class="header-anchor" href="#在-linux-mint-上安装-google-chrome" aria-label="Permalink to “在 Linux Mint 上安装 Google Chrome”">​</a></h3><p>进入 Google Chrome 的网站。</p>',7)),n("p",null,[e(i,{href:"https://www.google.com/chrome/index.html"},{default:s(()=>[...o[0]||(o[0]=[t("Google Chrome Website",-1)])]),_:1})]),o[23]||(o[23]=n("p",null,"你会看到一个 “Download Chrome” 的按钮。点击它。",-1)),o[24]||(o[24]=n("p",null,[n("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/download-chrome-linux-mint.png?resize=800%2C320&ssl=1",alt:"Download Chrome for Linux"})],-1)),o[25]||(o[25]=n("p",null,"它将向你显示在 Linux 上下载 Chrome 的两个选项。选择 Debian/Ubuntu 选项并点击 “Accept and Install” 按钮。",-1)),o[26]||(o[26]=n("p",null,[n("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/downloading-chrome-linux-mint.png?resize=800%2C679&ssl=1",alt:"Select Debian/Ubuntu option for Chrome package on Mint"})],-1)),n("p",null,[o[2]||(o[2]=t("在开始下载之前，Firefox 会询问你是否要用 Gdebi 打开下载的文件或保存它。你可以选择任何一个选项，因为最终你会 ",-1)),e(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:s(()=>[...o[1]||(o[1]=[t("使用 Gdebi 来安装 deb 文件",-1)])]),_:1}),o[3]||(o[3]=t("。然而，我更喜欢先保存文件。",-1))]),o[27]||(o[27]=n("p",null,[n("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/saving-downloaded-chrome-linux-mint.png?resize=798%2C400&ssl=1",alt:"Save the deb file"})],-1)),o[28]||(o[28]=n("p",null,"等待下载完成。",-1)),o[29]||(o[29]=n("p",null,[n("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/finishing-chrome-download-linux-mint.png?resize=799%2C315&ssl=1",alt:"Wait for Google Chrome download to finish"})],-1)),n("p",null,[o[5]||(o[5]=t("下载完成后，在文件管理器中进入下载文件夹。要 ",-1)),e(i,{href:"https://itsfoss.com/install-deb-files-ubuntu/"},{default:s(()=>[...o[4]||(o[4]=[t("安装 deb 文件",-1)])]),_:1}),o[6]||(o[6]=t("，可以双击它或者右击它并选择 “Open With GDebi Package Installer”。",-1))]),o[30]||(o[30]=l('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-google-chrome-deb-file-mint.png?resize=799%2C529&amp;ssl=1" alt="Double click on the downloaded deb file to install it"></p><p>等待几秒钟，它应该给你一个安装的选项。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-google-chrome-gdebi-mint.png?resize=801%2C548&amp;ssl=1" alt="Hit the Install Package option in Gdebi"></p><p>它将要求你提供 Linux Mint 的账户密码。在 Linux 中，你需要提供你的密码来安装任何应用。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/enter-password-for-installing-chrome-mint.png?resize=800%2C399&amp;ssl=1" alt="Enter your password for installing an application"></p><p>你就要完成了。它将显示哪些额外的软件包将与之一起安装（如果有的话）。点击继续按钮即可。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-chrome-mint.png?resize=799%2C483&amp;ssl=1" alt="Details on the packages to be installed"></p><p>安装完成应该只需要几秒钟或最多一分钟。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-chrome-mint-progress.png?resize=799%2C489&amp;ssl=1" alt="Installing Chrome in progress"></p><p>安装完成后，你应该看到这样的屏幕。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/chrome-installed-mint.png?resize=798%2C483&amp;ssl=1" alt="Chrome successfully installed on Linux Mint"></p><p>安装完成后，你可以在应用菜单中寻找 Google Chrome 来运行它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/run-google-chrome-linux-mint.png?resize=798%2C580&amp;ssl=1" alt="Run Google Chrome in Linux Mint"></p><p>然后在 Linux Mint 上享受 Google Chrome。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/google-chrome-in-linux-mint-800x450.webp" alt="Google Chrome running in Linux Mint"></p><h3 id="如何在-linux-mint-上更新-google-chrome" tabindex="-1">如何在 Linux Mint 上更新 Google Chrome <a class="header-anchor" href="#如何在-linux-mint-上更新-google-chrome" aria-label="Permalink to “如何在 Linux Mint 上更新 Google Chrome”">​</a></h3><p>这个方法的好处是，谷歌浏览器会随着系统的更新而更新。当你安装 deb 文件的时候，它也会在你的系统中添加一个来自谷歌的仓库。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/google-chrome-repo-added-mint.png?resize=799%2C272&amp;ssl=1" alt="Chrome adds a repository to the system for providing updates"></p><p>由于这个添加的仓库，Chrome 浏览器上的更新将被添加到系统更新中。因此，当你更新 Linux Mint 时，它也会被更新（如果有可用的更新）。</p><h3 id="如何从-linux-mint-中删除-google-chrome" tabindex="-1">如何从 Linux Mint 中删除 Google Chrome <a class="header-anchor" href="#如何从-linux-mint-中删除-google-chrome" aria-label="Permalink to “如何从 Linux Mint 中删除 Google Chrome”">​</a></h3><p>不喜欢 Chrome？不用担心。你可以从 Linux Mint 中卸载谷歌浏览器。同样这次你也不需要使用终端。</p><p>点击菜单，搜索 Chrome。在 Chrome 图标上点击右键，你会看到一个 “Uninstall” 选项。选择它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/removing-google-chrome-from-mint.webp" alt="Removing Google Chrome from Linux Mint"></p><p>当然，你必须输入你的密码。它将显示要删除的软件包。在这里点击 OK。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/uninstalling-google-chrome-from-linux-mint.webp" alt="Uninstalling Google Chrome from Linux mint"></p><p>你可以留下 Google Chrome 的仓库，也可以删除它。这是你的选择。</p><p>我希望你觉得这个教程对在 Linux Mint 上使用 Google Chrome 有帮助。</p><hr>',28)),n("p",null,[o[8]||(o[8]=t("via: ",-1)),e(i,{href:"https://itsfoss.com/install-chrome-linux-mint/"},{default:s(()=>[...o[7]||(o[7]=[t("https://itsfoss.com/install-chrome-linux-mint/",-1)])]),_:1})]),n("p",null,[o[13]||(o[13]=t("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:s(()=>[...o[9]||(o[9]=[t("Abhishek Prakash",-1)])]),_:1}),o[14]||(o[14]=t(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...o[10]||(o[10]=[t("lujun9972",-1)])]),_:1}),o[15]||(o[15]=t(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:s(()=>[...o[11]||(o[11]=[t("geekpi",-1)])]),_:1}),o[16]||(o[16]=t(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...o[12]||(o[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[19]||(o[19]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[17]||(o[17]=[t("LCTT",-1)])]),_:1}),o[20]||(o[20]=t(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...o[18]||(o[18]=[t("Linux中国",-1)])]),_:1}),o[21]||(o[21]=t(" 荣誉推出",-1))])])}const G=p(g,[["render",u]]);export{L as __pageData,G as default};
